-- Eventora OS — SQL file 13 check: buy-first onboarding. Every row should say OK.
select 'column tenants.owner_email' as item, case when exists (select 1 from information_schema.columns where table_schema='public' and table_name='tenants' and column_name='owner_email') then 'OK' else 'MISSING - run 13' end as status
union all select 'table purchases', case when to_regclass('public.purchases') is not null then 'OK' else 'MISSING - run 13' end
union all select 'one business per admin email (unique index)', case when exists (select 1 from pg_indexes where indexname='tenants_owner_email_uq') then 'OK' else 'MISSING - run 13' end
union all select 'every business has an admin email', case when exists (select 1 from public.tenants where owner_email is null) then 'CHECK - some businesses have no owner_email (they cannot be reconnected by email)' else 'OK' end
union all select 'function claim_purchase (signed-in only)', case when to_regprocedure('public.claim_purchase()') is null then 'MISSING - run 13' when has_function_privilege('anon','public.claim_purchase()','EXECUTE') then 'PROBLEM' else 'OK' end
union all select 'visitors cannot read purchases', case when has_table_privilege('anon','public.purchases','SELECT') or has_table_privilege('authenticated','public.purchases','SELECT') then 'PROBLEM' else 'OK' end
union all select 'only the server can record payments (purchase_event)', case when to_regprocedure('public.purchase_event(text,text,text,text,timestamptz,text,integer)') is null then 'MISSING - run 13' when has_function_privilege('anon','public.purchase_event(text,text,text,text,timestamptz,text,integer)','EXECUTE') or has_function_privilege('authenticated','public.purchase_event(text,text,text,text,timestamptz,text,integer)','EXECUTE') then 'PROBLEM' else 'OK' end
union all select 'thank-you page can read its own purchase', case when has_function_privilege('anon','public.purchase_status(uuid,text)','EXECUTE') then 'OK' else 'MISSING - run 13' end;
